def _filter_gitignored(candidates: list[str]) -> list[str]:
    """Remove gitignored paths; fall back to all candidates on error."""
    if not candidates:
        return []
    try:
        proc = subprocess.run(
            ["git", "check-ignore", "--stdin", "--no-index"],
            input="\n".join(candidates),
            capture_output=True,
            text=True,
            cwd=str(REPO_ROOT),
            timeout=30,
        )
        ignored = set(proc.stdout.splitlines())
        return [c for c in candidates if c not in ignored]
    except (subprocess.SubprocessError, OSError):
        return candidates


def _render_py_tree(shown: list[str]) -> str:
    """Render an indented tree of relative paths."""
    tree_lines: list[str] = []
    for rel in shown:
        parts = rel.split("/")
        indent = "    " * (len(parts) - 1)
        tree_lines.append(f"{indent}└── {parts[-1]}")
    return "\n".join(tree_lines)


